{
  "name": "Mara's Cache Optimization",
  "hypothesis": "Previous failures stemmed from agents carrying insufficient cargo (often 1 or 2 items) before depositing, leading to high travel costs relative to food gained. The data shows that maximizing cargo to the full capacity of 3 units before every return trip optimizes the food-per-distance ratio. By enforcing a mandatory deposit trigger specifically when cargo equals 3 ('cargo==3'), agents will harvest until full, then return immediately. This ensures every journey maximizes load, allowing more frequent harvesting cycles within the 720-step limit compared to strategies that force deposits at lower cargo levels or rely on erratic tiredness triggers.",
  "rules": [
    {
      "when": "always",
      "do": "explore"
    },
    {
      "when": "foodNear",
      "do": "gather"
    },
    {
      "when": "tired",
      "do": "rest"
    },
    {
      "when": "cargo==3",
      "do": "deposit"
    }
  ]
}
